		var update replicateMessage
		if err := json.Unmarshal(msg.Body, &update); err != nil {
			return fmt.Errorf("decode replication message: %w", err)
		}
		c.merge(update.Value)
		return nil
	})

	if err := n.Run(); err != nil {
		log.Fatalf("node failed: %v", err)
	}
